var draco = null;
function gltfLoader() {
  const loader = new GLTFLoader();
  if (typeof window !== "undefined") {
    draco ??= new DRACOLoader().setDecoderPath("/draco/");
    loader.setDRACOLoader(draco);
  }
  loader.setMeshoptDecoder(MeshoptDecoder);
  return loader;
}

